test('named greeting', () => {
  assert.deepEqual(greeting('developer'), { message: 'hello developer' });
});

test('padded name trims whitespace', () => {
  assert.deepEqual(greeting('  developer  '), { message: 'hello developer' });
});

test('whitespace-only name falls back to world', () => {
  assert.deepEqual(greeting('   '), { message: 'hello world' });
  assert.deepEqual(greeting('\t\n'), { message: 'hello world' });
});

